// d45: what the import funnel's first two probes answer for a folder.
import AVFoundation
import AppKit
import ImageIO

let base = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
let fm = FileManager.default
try? fm.removeItem(at: base)
try fm.createDirectory(at: base, withIntermediateDirectories: true)
let plain = base.appendingPathComponent("Shoot")
let movieNamed = base.appendingPathComponent("Shoot.mov")
let imageNamed = base.appendingPathComponent("Shoot.png")
for folder in [plain, movieNamed, imageNamed] {
    try fm.createDirectory(at: folder, withIntermediateDirectories: true)
    fm.createFile(atPath: folder.appendingPathComponent("a.txt").path, contents: Data("x".utf8))
}

// The pasteboard read MediaPane does, on a private pasteboard.
let pb = NSPasteboard(name: NSPasteboard.Name("d45.private"))
pb.clearContents()
pb.writeObjects([plain as NSURL])
let read = pb.readObjects(
    forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL]
print("pasteboard folder url:", read ?? [], "hasDirectoryPath:", read?.first?.hasDirectoryPath ?? false)
print("lastPathComponent:", read?.first?.lastPathComponent ?? "nil")

let sem = DispatchSemaphore(value: 0)
Task.detached {
    for url in [plain, movieNamed, read?.first ?? plain] {
        let asset = AVURLAsset(
            url: url, options: [AVURLAssetPreferPreciseDurationAndTimingKey: true])
        do {
            let duration = try await asset.load(.duration)
            print(url.lastPathComponent, "duration:", duration.seconds, "numeric:", duration.isNumeric)
        } catch {
            print(url.lastPathComponent, "duration threw:", error)
        }
    }
    sem.signal()
}
_ = sem.wait(timeout: .now() + 30)

let source = CGImageSourceCreateWithURL(imageNamed as CFURL, nil)
print("image source for folder:", source == nil ? "nil" : "count \(CGImageSourceGetCount(source!))")
pb.releaseGlobally()

